//! The basis of a refusal, which `basis()` answers from the `Basis:` line of the variant's doc
//! comment (`error/basis.rs`, generated by `scripts/refusal-surface/refusal_surface.py`).

use crate::RefusalBasis::{Device, MetalDocumented, MetalMeasured, Ours};
use crate::{Error, Gap, Limit, LinearPlanePassKind, Refusal};
use metal2vulkan::error::Error as Translator;

/// A variant of each basis `Refusal`, `Limit` and `Gap` declare answers it.
#[test]
fn each_refusal_enum_answers_its_declared_basis() {
    assert_eq!(Refusal::EmptyBuffer.basis(), MetalMeasured);
    assert_eq!(Refusal::Committed.basis(), MetalDocumented);
    assert_eq!(Refusal::ManagedCopyMissing.basis(), Ours);
    let kind = LinearPlanePassKind::DepthStencil;
    assert_eq!(Limit::DeviceSamplers { max: 16 }.basis(), Device);
    assert_eq!(Limit::BlockIds.basis(), Ours);
    assert_eq!(Gap::LinearPlanePass { kind }.basis(), Device);
    assert_eq!(Gap::LodClamps.basis(), Ours);
}

/// A refusal enum's variant answers its own; a device that lacks the floor's mechanism `Device`;
/// a translator's refusal, a failed call and the consumer's own state none.
#[test]
fn an_error_answers_the_basis_of_what_it_carries() {
    let cases = [
        (Error::Refused(Refusal::Committed), Some(MetalDocumented)),
        (Error::Limit(Limit::BlockIds), Some(Ours)),
        (Error::Unsupported(Gap::LodClamps), Some(Ours)),
        (Error::NoDirectDriverLoading, Some(Device)),
        (Error::translation(Translator::Cancelled), None),
        (Error::out_of_device_memory(), None),
        (Error::Quiesced, None),
    ];
    for (error, basis) in cases {
        assert_eq!(error.basis(), basis, "{error}");
    }
}
